const fs = require("fs");
const fsp = require("fs/promises");
const path = require("path");
const os = require("os");
// Node.js's built-ins from an npm package: fs (sync, callbacks, promises, streams), process,
// os, timers. Prints what it found; the same package under Node.js prints the same.
module.exports = async function run() {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "tov-node-"));
  try {
    await body(dir);
  } catch (e) {
    process.stdout.write("FAILED " + (e && e.stack || e) + "\n");
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
};
async function body(dir) {
  const out = [];
  const log = (...a) => out.push(a.join(" "));
  const f = path.join(dir, "a.txt");
  fs.writeFileSync(f, "héllo\n");
  fs.appendFileSync(f, "more");
  log("read", JSON.stringify(fs.readFileSync(f, "utf8")), fs.readFileSync(f).length, fs.existsSync(f), fs.existsSync(f + "x"));
  const st = fs.statSync(f);
  log("stat", st.size, st.isFile(), st.isDirectory(), typeof st.mtimeMs, st.mtime instanceof Date);
  fs.mkdirSync(path.join(dir, "d/e/f"), { recursive: true });
  fs.writeFileSync(path.join(dir, "d/x.json"), JSON.stringify({ a: 1 }));
  log("readdir", fs.readdirSync(dir).sort().join(","), fs.readdirSync(path.join(dir, "d"), { withFileTypes: true }).map((e) => e.name + (e.isDirectory() ? "/" : "")).sort().join(","));
  try { fs.readFileSync(path.join(dir, "nope")); } catch (e) { log("error", e.code, e.errno, e.syscall, e.message.replace(dir, "DIR")); }
  fs.renameSync(f, path.join(dir, "b.txt"));
  fs.copyFileSync(path.join(dir, "b.txt"), path.join(dir, "c.txt"));
  log("rename+copy", fs.readdirSync(dir).sort().join(","));
  const fd = fs.openSync(path.join(dir, "c.txt"), "r");
  const buf = Buffer.alloc(3);
  log("fd read", fs.readSync(fd, buf, 0, 3, 1), buf.toString());
  fs.closeSync(fd);
  log("json", JSON.parse(await fsp.readFile(path.join(dir, "d/x.json"), "utf8")).a);
  await new Promise((res) => fs.readFile(path.join(dir, "b.txt"), "utf8", (err, data) => { log("callback", err, JSON.stringify(data)); res(); }));
  const fh = await fsp.open(path.join(dir, "b.txt"));
  log("filehandle", (await fh.readFile("utf8")).length, typeof fh.fd);
  await fh.close();
  await fsp.writeFile(path.join(dir, "p.txt"), "promised");
  log("promises", await fsp.readFile(path.join(dir, "p.txt"), "utf8"), (await fsp.stat(path.join(dir, "p.txt"))).size);
  fs.rmSync(path.join(dir, "d"), { recursive: true });
  log("rm", fs.existsSync(path.join(dir, "d")));
  const stream = fs.createReadStream(path.join(dir, "b.txt"), { encoding: "utf8" });
  let streamed = "";
  for await (const chunk of stream) streamed += chunk;
  log("stream", JSON.stringify(streamed));
  await new Promise((res) => { const w = fs.createWriteStream(path.join(dir, "w.txt")); w.write("one "); w.end("two", res); });
  log("writestream", fs.readFileSync(path.join(dir, "w.txt"), "utf8"));
  log("process", process.platform, typeof process.pid, process.argv.length >= 1, typeof process.env.HOME, typeof process.cwd());
  log("os", os.platform(), os.type(), os.cpus().length > 0, os.totalmem() > 0, typeof os.hostname(), os.homedir() === process.env.HOME, os.EOL === "\n");
  const t0 = Date.now();
  await new Promise((res) => setTimeout(res, 20));
  log("timer", Date.now() - t0 >= 19);
  await new Promise((res) => setImmediate(res));
  log("immediate ok");
  process.stdout.write(out.join("\n") + "\n");
};
